#!/usr/bin/env python3
"""Create owned A/B snapshots and explicitly separate instrumented binaries."""
import hashlib
import json
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[2]
HERE = Path(__file__).resolve().parent
REFERENCE = ROOT / 'build/verification/run.B1HO3G/source-hashes.json'
REMOVE = '    refill(r);\n    if (!r->query->no_ignore) {'
REPLACE = '    if (!r->query->no_ignore) {'

PROBE = '''#include <time.h>
/* Experiment only: no probe code enters the application working tree. */
static struct Probe {
    size_t sync_roots;
    size_t sync_children;
    size_t full_fallbacks;
    size_t full_with_done;
    size_t full_all_done;
    size_t worker_jobs;
    size_t active;
    size_t peak_active;
    int threads;
    double worker_wall_ns;
    double worker_cpu_ns;
    double app_wall_start;
    double coordinator_cpu_start;
} probe;

static double probe_clock(clockid_t clock)
{
    struct timespec value;
    if (clock_gettime(clock, &value) != 0)
        abort();
    return (double)value.tv_sec * 1000000000.0 + (double)value.tv_nsec;
}

'''


def replace(text, old, new):
    assert text.count(old) == 1, old
    return text.replace(old, new, 1)


def instrument(tree):
    main = tree / 'src/fynd.c'
    text = main.read_text()
    text = replace(text, '#include "listing.inc"', PROBE + '#include "listing.inc"')
    text = replace(text, '    int verdict;\n    char *joined;',
                   '    int verdict;\n    int probe_i;\n    int probe_done;\n    char *joined;')
    text = replace(text, '    if (job == NULL) {\n        listing_init(&local, path);', '''    if (job == NULL) {
        if (depth == 0)
            ++probe.sync_roots;
        else {
            ++probe.sync_children;
            if (r->pool != NULL) {
                cu_mutex_lock(r->pool->mutex);
                if (r->pool->pending == r->pool->count) {
                    ++probe.full_fallbacks;
                    probe_done = 0;
                    for (probe_i = 0; probe_i < r->pool->count; ++probe_i)
                        if (r->pool->slots[probe_i] != NULL &&
                            r->pool->slots[probe_i]->state == 3)
                            ++probe_done;
                    if (probe_done != 0)
                        ++probe.full_with_done;
                    if (probe_done == r->pool->count)
                        ++probe.full_all_done;
                }
                cu_mutex_unlock(r->pool->mutex);
            }
        }
        listing_init(&local, path);''')
    text = replace(text, '    cu_arena_init(&arena);\n    status = fynd_run', '''    probe.app_wall_start = probe_clock(CLOCK_MONOTONIC);
    probe.coordinator_cpu_start = probe_clock(CLOCK_THREAD_CPUTIME_ID);
    cu_arena_init(&arena);
    status = fynd_run''')
    text = replace(text, '    cu_arena_release(&arena);\n    return status;', '''    cu_arena_release(&arena);
    (void)fprintf(stderr,
        "FYND_PROBE {\\"sync_roots\\":%lu,\\"sync_children\\":%lu,"
        "\\"full_fallbacks\\":%lu,\\"full_with_done\\":%lu,\\"full_all_done\\":%lu,"
        "\\"worker_jobs\\":%lu,\\"peak_active\\":%lu,\\"threads\\":%d,"
        "\\"worker_wall_ns\\":%.0f,\\"worker_cpu_ns\\":%.0f,"
        "\\"coordinator_cpu_ns\\":%.0f,\\"app_wall_ns\\":%.0f}\\n",
        (unsigned long)probe.sync_roots, (unsigned long)probe.sync_children,
        (unsigned long)probe.full_fallbacks, (unsigned long)probe.full_with_done,
        (unsigned long)probe.full_all_done, (unsigned long)probe.worker_jobs,
        (unsigned long)probe.peak_active, probe.threads,
        probe.worker_wall_ns, probe.worker_cpu_ns,
        probe_clock(CLOCK_THREAD_CPUTIME_ID) - probe.coordinator_cpu_start,
        probe_clock(CLOCK_MONOTONIC) - probe.app_wall_start);
    return status;''')
    main.write_text(text.replace('probe.', 'schedule_probe.').replace('} probe;', '} schedule_probe;'))
    path = tree / 'src/listing.inc'
    text = path.read_text()
    text = replace(text, '    int i;\n    worker = (ListingWorker *)context;', '''    int i;
    double cpu_start;
    double job_start;
    double job_end;
    cpu_start = probe_clock(CLOCK_THREAD_CPUTIME_ID);
    worker = (ListingWorker *)context;''')
    text = replace(text, '''        cu_mutex_unlock(pool->mutex);
        listing_collect(job);
        cu_mutex_lock(pool->mutex);
        job->state = 3;''', '''        ++probe.active;
        if (probe.active > probe.peak_active)
            probe.peak_active = probe.active;
        job_start = probe_clock(CLOCK_MONOTONIC);
        cu_mutex_unlock(pool->mutex);
        listing_collect(job);
        job_end = probe_clock(CLOCK_MONOTONIC);
        cu_mutex_lock(pool->mutex);
        --probe.active;
        ++probe.worker_jobs;
        probe.worker_wall_ns += job_end - job_start;
        job->state = 3;''')
    text = replace(text, '''    }
    cu_mutex_unlock(pool->mutex);
}

static void pool_cancel''', '''    }
    probe.worker_cpu_ns += probe_clock(CLOCK_THREAD_CPUTIME_ID) - cpu_start;
    cu_mutex_unlock(pool->mutex);
}

static void pool_cancel''')
    text = replace(text, '    pool->count = count;', '    pool->count = count;\n    probe.threads = count;')
    path.write_text(text.replace('probe.', 'schedule_probe.'))


if __name__ == '__main__':
    reference = json.loads(REFERENCE.read_text())['fynd']
    for name in ('src/fynd.c', 'src/listing.inc', 'src/ignore.inc', 'tests/test_parallel.c', 'bench/bench.py'):
        assert hashlib.sha256((ROOT / name).read_bytes()).hexdigest() == reference[name], name
    metadata = {'scope': 'single early-refill deletion; production tree unchanged',
                'baseline_receipt': 'build/verification/run.B1HO3G',
                'cutils_revision': (ROOT / 'CUTILS_REVISION').read_text().strip(),
                'variants': {}}
    for variant in ('before', 'branch', 'probe-before', 'probe-branch'):
        tree = HERE / variant
        tree.mkdir(exist_ok=False)
        for name in ('src', 'cmd', 'include', 'tests'):
            shutil.copytree(ROOT / name, tree / name, ignore=shutil.ignore_patterns('__pycache__', '*.pyc'))
        for name in ('Makefile', 'dcheck.conf', 'CUTILS_REVISION'):
            shutil.copyfile(ROOT / name, tree / name)
        if variant.endswith('branch'):
            path = tree / 'src/fynd.c'
            path.write_text(replace(path.read_text(), REMOVE, REPLACE))
            # The old fixture forced ancestor refill. Preserve its overlap and
            # budget checks, but require the nested branch to run on a worker.
            path = tree / 'tests/test_parallel.c'
            path.write_text(replace(path.read_text(),
                'assert(job->state == 0); /* Later siblings occupy both global tokens. */',
                'assert(job->state == 2); /* Current branch wins the refunded token. */'))
        if variant.startswith('probe-'):
            instrument(tree)
        metadata['variants'][variant] = {
            name: hashlib.sha256((tree / name).read_bytes()).hexdigest()
            for name in ('src/fynd.c', 'src/listing.inc', 'tests/test_parallel.c')}
    (HERE / 'inputs.json').write_text(json.dumps(metadata, indent=2) + '\n')
    print('Prepared four owned snapshots; native measurements will not use probe binaries')

