typedef struct WalkEntry {
    CuStr name;
    CuDirKind kind;
    ListingJob *prefetch;
    int eligible;
} WalkEntry;
struct ListingJob {
    CuArena arena;
    char *path;
    CuVec entries;
    int error;
    int operation;
    int state;
    int token;
};
typedef struct ListingWorker {
    Pool *pool;
    CuThread *thread;
} ListingWorker;
struct Pool {
    CuArena arena;
    CuMutex *mutex;
    CuCond *work;
    CuCond *completed;
    ListingWorker workers[32];
    ListingJob *slots[32];
