#include "fynd.h"
#include "cu.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/stat.h>

typedef struct Query {
    CuStr pattern;
    CuVec extensions;
    CuVec roots;
    unsigned int kinds;
    int fold;
    int hidden;
    int delimiter;
    int depth;
    int no_ignore;
    int threads;
} Query;

typedef struct ActiveFrame ActiveFrame;
typedef struct Pool Pool;

typedef struct Run {
    CuArena *arena;
    const Query *query;
    FILE *out;
    FILE *err;
    int status;
    int stop;
    Pool *pool;
    ActiveFrame *active;
} Run;

static int diagnostic(Run *r, const char *message, const char *path)
{
    const unsigned char *p;
    int ok;
    ok = fputs("fynd: ", r->err) >= 0 && fputs(message, r->err) >= 0;
    if (path != NULL) {
        if (fputs(" '", r->err) < 0)
            ok = 0;
        for (p = (const unsigned char *)path; *p != 0; ++p) {
            if (*p >= 32 && *p <= 126 && *p != '\\' && *p != '\'') {
                if (fputc((int)*p, r->err) == EOF)
                    ok = 0;
            } else if (fprintf(r->err, "\\x%02x", (unsigned int)*p) < 0)
                ok = 0;
            if (!ok)
                break;
        }
        if (fputc('\'', r->err) == EOF)
            ok = 0;
    }
    if (fputc('\n', r->err) == EOF || fflush(r->err) == EOF || ferror(r->err))
        ok = 0;
    if (!ok)
        r->stop = 1;
    return ok;
}

static void failure(Run *r, const char *message, const char *path, int terminal)
{
    r->status = 1;
    if (terminal)
        r->stop = 1;
    (void)diagnostic(r, message, path);
}

static unsigned char folded(unsigned char c, int fold)
{
    if (fold && c >= 'A' && c <= 'Z')
        return (unsigned char)(c + ('a' - 'A'));
    return c;
}

static int contains(CuStr name, CuStr pattern, int fold)
{
    size_t i;
    size_t j;
    if (pattern.len > name.len)
        return 0;
    for (i = 0; i <= name.len - pattern.len; ++i) {
        for (j = 0; j < pattern.len; ++j)
            if (folded((unsigned char)name.ptr[i + j], fold) !=
                folded((unsigned char)pattern.ptr[j], fold))
                break;
        if (j == pattern.len)
            return 1;
    }
    return 0;
}

static CuStr basename_view(const char *path)
{
    const char *last;
    const char *p;
    last = path;
    for (p = path; *p != 0; ++p)
        if (*p == '/' && p[1] != 0)
            last = p + 1;
    return cu_str_n(last, strlen(last));
}

static int selected(const Query *q, CuStr name, CuDirKind kind)
{
    size_t i;
    size_t dot;
    CuStr ext;
    const CuStr *wanted;
    if (q->kinds != 0 && (q->kinds & (1U << (unsigned int)kind)) == 0)
        return 0;
    if (!contains(name, q->pattern, q->fold))
        return 0;
    if (q->extensions.len == 0)
        return 1;
    dot = 0;
    for (i = 0; i < name.len; ++i)
        if (name.ptr[i] == '.')
            dot = i;
    if (dot == 0 || dot + 1 == name.len)
        return 0;
    ext = cu_str_n(name.ptr + dot + 1, name.len - dot - 1);
    for (i = 0; i < q->extensions.len; ++i) {
        wanted = CU_VEC_AT(&q->extensions, CuStr, i);
        if (ext.len == wanted->len && contains(ext, *wanted, q->fold))
            return 1;
    }
    return 0;
}

static int joined_size(size_t a, size_t b, int slash, size_t *size)
{
    size_t extra;
    extra = slash ? 2U : 1U;
    if (b > (size_t)-1 - extra || a > (size_t)-1 - b - extra)
        return 0;
    *size = a + b + extra;
    return 1;
}

static char *join_path(CuArena *a, const char *parent, CuStr name)
{
    size_t n;
    size_t total;
    int slash;
    char *path;
    n = strlen(parent);
    slash = n != 0 && parent[n - 1] != '/';
    if (!joined_size(n, name.len, slash, &total))
        return NULL;
    path = cu_arena_push_bytes(a, total);
    if (path == NULL)
        return NULL;
    memcpy(path, parent, n);
    if (slash)
        path[n++] = '/';
    memcpy(path + n, name.ptr, name.len);
    path[n + name.len] = 0;
    return path;
}

#include "listing.inc"
#include "ignore.inc"

struct ActiveFrame {
    ActiveFrame *parent;
    ListingJob *job;
    size_t next;
    size_t scan;
};

#ifndef FYND_PREFETCH_SCAN
#define FYND_PREFETCH_SCAN() ((void)0)
#endif

static void ignore_failure(Run *r, const IgnoreError *error)
{
    failure(r, listing_resource(error->number) ? "ignore resource failure" :
            "cannot load ignore rules", error->path, listing_resource(error->number));
}

/* All eligibility is cached only after this directory's complete rules load.
 * The independent scan cursor considers each remaining entry at most once.
 * Jobs are allocated in the owning listing, never a coordinator child scope. */
static void refill(Run *r)
{
    ActiveFrame *frame;
    WalkEntry *entry;
    ListingJob *job;
    char *path;
    size_t i;
    if (r->pool == NULL || r->stop)
        return;
    for (frame = r->active; frame != NULL; frame = frame->parent) {
        for (i = frame->scan > frame->next ? frame->scan : frame->next;
             i < frame->job->entries.len; ++i, frame->scan = i) {
            if (r->pool->pending == r->pool->count)
                return;
            FYND_PREFETCH_SCAN();
            entry = CU_VEC_AT(&frame->job->entries, WalkEntry, i);
            if (entry->eligible != 2 || entry->prefetch != NULL)
                continue;
            path = join_path(&frame->job->arena, frame->job->path, entry->name);
            job = CU_PUSH(&frame->job->arena, ListingJob, 1);
            if (path == NULL || job == NULL) {
                failure(r, "allocation failure", frame->job->path, 1);
                return;
            }
            listing_init(job, path);
            if (!listing_submit(r->pool, job)) {
                listing_release(r->pool, job);
                return;
            }
            entry->prefetch = job;
        }
    }
}

static void visit(Run *r, const char *path, CuStr name, CuDirKind kind, int depth,
                  const IgnoreFrame *parent, ListingJob *prefetch)
{
    CuTemp directory;
    CuTemp child;
    ListingJob local;
    ListingJob *job;
    ActiveFrame frame;
    const IgnoreFrame *rules;
    IgnoreError error;
    WalkEntry *entry;
    ListingJob *attached;
    unsigned listed;
    size_t i;
    int verdict;
    char *joined;
    if (selected(r->query, name, kind)) {
        if (fputs(path, r->out) < 0 || fputc(r->query->delimiter, r->out) == EOF ||
            ferror(r->out)) {
            failure(r, "output failure", NULL, 1);
            goto unused;
        }
    }
    if (kind != CU_DIR_DIR || depth == r->query->depth)
        goto unused;
    if (depth == 128) {
        failure(r, "recursion safety limit", path, 0);
        goto unused;
    }
    directory = cu_temp_begin(r->arena);
    rules = parent;
    job = prefetch;
    if (job == NULL) {
        listing_init(&local, path);
        job = &local;
        listing_collect(job);
    } else
        listing_adopt(r->pool, job);
    if (job->error != 0) {
        failure(r, job->error == ENOMEM ? "allocation failure" :
                (job->operation == 1 ? "cannot open directory" : "cannot list directory"),
                path, listing_resource(job->error));
        goto done;
    }
    if (!r->query->no_ignore) {
        if (parent == NULL && !ignore_seed(r->arena, path, &rules, &error)) {
            ignore_failure(r, &error);
            goto done;
        }
        listed = 0;
        for (i = 0; i < job->entries.len; ++i) {
            entry = CU_VEC_AT(&job->entries, WalkEntry, i);
            listed |= ignore_listing_bit(entry->name);
        }
        if (!ignore_enter(r->arena, rules, path, listed, &rules, &error)) {
            ignore_failure(r, &error);
            goto done;
        }
    }
    for (i = 0; i < job->entries.len && !r->stop; ++i) {
        entry = CU_VEC_AT(&job->entries, WalkEntry, i);
        if (!r->query->hidden && entry->name.ptr[0] == '.')
            continue;
        if (r->query->no_ignore)
            entry->eligible = 1;
        else {
            child = cu_temp_begin(r->arena);
            joined = join_path(r->arena, path, entry->name);
            verdict = 0;
            if (joined == NULL)
                failure(r, "allocation failure", path, 1);
            else if (!ignore_verdict(r->arena, rules, joined, entry->kind == CU_DIR_DIR,
                                     &verdict, &error))
                ignore_failure(r, &error);
            else if (verdict != 1)
                entry->eligible = 1;
            cu_temp_end(child);
        }
        if (entry->eligible == 1 && entry->kind == CU_DIR_DIR &&
            depth + 1 != r->query->depth && depth + 1 < 128)
            entry->eligible = 2;
    }
    frame.parent = r->active;
    frame.job = job;
    frame.next = 0;
    frame.scan = 0;
    r->active = &frame;
    refill(r);
    for (i = 0; i < job->entries.len && !r->stop; ++i) {
        frame.next = i + 1;
        entry = CU_VEC_AT(&job->entries, WalkEntry, i);
        if (entry->eligible == 0)
            continue;
        child = cu_temp_begin(r->arena);
        joined = join_path(r->arena, path, entry->name);
        attached = entry->prefetch;
        entry->prefetch = NULL;
        if (joined == NULL) {
            failure(r, "allocation failure", path, 1);
            if (attached != NULL)
                listing_release(r->pool, attached);
        } else
            visit(r, joined, entry->name, entry->kind, depth + 1, rules, attached);
        cu_temp_end(child);
        refill(r);
    }
    r->active = frame.parent;
done:
    if (r->stop && r->pool != NULL)
        pool_cancel(r->pool);
    listing_release(r->pool, job);
    cu_temp_end(directory);
    return;
unused:
    if (r->stop && r->pool != NULL)
        pool_cancel(r->pool);
    if (prefetch != NULL)
        listing_release(r->pool, prefetch);
}

static int parse_depth(const char *s, int *out)
{
    int value;
    unsigned int digit;
    if (*s == 0)
        return 0;
    value = 0;
    while (*s != 0) {
        if (*s < '0' || *s > '9')
            return 0;
        digit = (unsigned int)(*s - '0');
        if (value > 12 || (value == 12 && digit > 8))
            return 0;
        value = value * 10 + (int)digit;
        ++s;
    }
    *out = value;
    return 1;
}

static int parse_threads(const char *s, int *out)
{
    int value;
    if (!parse_depth(s, &value) || value < 1 || value > 32)
        return 0;
    *out = value;
    return 1;
}

static int parse(Query *q, CuArena *arena, int argc, char **argv)
{
    int i;
    const char *s;
    const char *value;
    CuStr view;
    unsigned int kind;
    q->pattern = cu_str_n("", 0);
    CU_VEC_INIT(&q->extensions, arena, CuStr);
    CU_VEC_INIT(&q->roots, arena, CuStr);
    q->kinds = 0;
    q->fold = 0;
    q->hidden = 0;
    q->delimiter = '\n';
    q->depth = -1;
    q->threads = 1;
    q->no_ignore = 0;
    i = 1;
    while (i < argc) {
        s = argv[i];
        if (strcmp(s, "--") == 0) {
            ++i;
            break;
        }
        if (s[0] != '-' || s[1] == 0)
            break;
        ++i;
        if (strcmp(s, "-i") == 0 || strcmp(s, "--ignore-case") == 0)
            q->fold = 1;
        else if (strcmp(s, "-H") == 0 || strcmp(s, "--hidden") == 0)
            q->hidden = 1;
        else if (strcmp(s, "--no-ignore") == 0)
            q->no_ignore = 1;
        else if (strcmp(s, "-j") == 0 || strcmp(s, "--threads") == 0) {
            if (i == argc || !parse_threads(argv[i++], &q->threads))
                return 2;
        } else if (s[0] == '-' && s[1] == 'j') {
            if (!parse_threads(s + 2, &q->threads))
                return 2;
        } else if (strcmp(s, "-0") == 0 || strcmp(s, "--print0") == 0)
            q->delimiter = 0;
        else if (strcmp(s, "-t") == 0 || strcmp(s, "--type") == 0) {
            if (i == argc)
                return 2;
            value = argv[i++];
            if (strlen(value) != 1)
                return 2;
            switch (*value) {
            case 'f': kind = CU_DIR_FILE; break;
            case 'd': kind = CU_DIR_DIR; break;
            case 'l': kind = CU_DIR_LINK; break;
            case 'o': kind = CU_DIR_OTHER; break;
            default: return 2;
            }
            q->kinds |= 1U << kind;
        } else if (strcmp(s, "-e") == 0 || strcmp(s, "--extension") == 0) {
            if (i == argc)
                return 2;
            value = argv[i++];
            if (*value == 0 || strchr(value, '.') != NULL || strchr(value, '/') != NULL)
                return 2;
            view = cu_str_n(value, strlen(value));
            CU_VEC_PUSH(&q->extensions, &view);
            if (cu_vec_failed(&q->extensions))
                return 1;
        } else if (strcmp(s, "--max-depth") == 0) {
            if (i == argc || !parse_depth(argv[i++], &q->depth))
                return 2;
        } else
            return 2;
    }
    if (i < argc) {
        q->pattern = cu_str_n(argv[i], strlen(argv[i]));
        ++i;
    }
    if (i == argc) {
        view = cu_str_n(".", 1);
        CU_VEC_PUSH(&q->roots, &view);
    } else {
        for (; i < argc; ++i) {
            if (argv[i][0] == 0)
                return 2;
            view = cu_str_n(argv[i], strlen(argv[i]));
            CU_VEC_PUSH(&q->roots, &view);
            if (cu_vec_failed(&q->roots))
                return 1;
        }
    }
    return cu_vec_failed(&q->roots) ? 1 : 0;
}

static int fynd_run(int argc, char **argv, FILE *out, FILE *err, CuArena *arena)
{
    Query q;
    Run r;
    Pool pool;
    int pool_live;
    CuTemp root_scope;
    const CuStr *root;
    char *path;
    size_t n;
    size_t total;
    size_t i;
    struct stat st;
    CuDirKind kind;
    int parsed;
    r.arena = arena;
    r.query = &q;
    r.out = out;
    r.err = err;
    r.status = 0;
    r.stop = 0;
    r.pool = NULL;
    r.active = NULL;
    pool_live = 0;
    if (argc == 2 && (strcmp(argv[1], "-h") == 0 ||
        strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "--version") == 0)) {
        if (ferror(out)) {
            failure(&r, "output failure", NULL, 1);
            return r.status;
        }
        if (strcmp(argv[1], "--version") == 0)
            parsed = fputs("fynd 0.1.0\n", out);
        else
            parsed = fputs("Usage: fynd [OPTIONS] [--] [PATTERN [ROOT ...]]\n"
                "  -i, --ignore-case   ASCII case folding\n"
                "  -t, --type KIND     f, d, l, or o (union)\n"
                "  -e, --extension EXT final suffix (union)\n"
                "  -H, --hidden        include discovered hidden names\n"
                "  -0, --print0        NUL-delimited paths\n"
                "  --max-depth N       selection depth 0 through 128\n"
                "  --no-ignore         bypass ignore rules\n"
                "  -j N, --threads N   listing workers 1 through 32 (default 1)\n"
                "  -h, --help          show help alone\n"
                "  --version           show version alone\n", out);
        if (parsed < 0 || ferror(out))
            failure(&r, "output failure", NULL, 1);
    } else {
        parsed = parse(&q, arena, argc, argv);
        if (parsed != 0) {
            r.status = parsed;
            if (!diagnostic(&r, parsed == 2 ? "invalid invocation" : "allocation failure", NULL))
                r.status = 1;
        } else {
            /* Validate first: a pre-existing output error does not make usage valid. */
            if (ferror(out))
                failure(&r, "output failure", NULL, 1);
            if (!r.stop && q.threads > 1) {
                pool_live = 1;
                if (!pool_start(&pool, q.threads))
                    failure(&r, "cannot start listing workers", NULL, 1);
                else
                    r.pool = &pool;
            }
            for (i = 0; i < q.roots.len && !r.stop; ++i) {
                root = CU_VEC_AT(&q.roots, CuStr, i);
                root_scope = cu_temp_begin(arena);
                n = root->len;
                while (n > 1 && root->ptr[n - 1] == '/')
                    --n;
                path = joined_size(n, 0, 0, &total) ?
                    cu_arena_push_bytes(arena, total) : NULL;
                if (path == NULL)
                    failure(&r, "allocation failure", NULL, 1);
                else {
                    memcpy(path, root->ptr, n);
                    path[n] = 0;
                    if (lstat(path, &st) != 0)
                        failure(&r, "cannot stat root", path,
                            errno == ENOMEM || errno == EMFILE || errno == ENFILE);
                    else {
                        if (S_ISREG(st.st_mode)) kind = CU_DIR_FILE;
                        else if (S_ISDIR(st.st_mode)) kind = CU_DIR_DIR;
                        else if (S_ISLNK(st.st_mode)) kind = CU_DIR_LINK;
                        else kind = CU_DIR_OTHER;
                        visit(&r, path, basename_view(path), kind, 0, NULL, NULL);
                    }
                }
                cu_temp_end(root_scope);
            }
        }
    }
    if (pool_live)
        pool_finish(&pool);
    if (fflush(out) == EOF || (r.status != 2 && ferror(out)))
        failure(&r, "output flush failure", NULL, 1);
    return r.status;
}

int fynd_main(int argc, char **argv, FILE *out, FILE *err)
{
    CuArena arena;
    int status;
    cu_arena_init(&arena);
    status = fynd_run(argc, argv, out, err, &arena);
    cu_arena_release(&arena);
    return status;
}

branch.src/listing.inc:
/* Stable listings: only collectors mutate entries before DONE publication.
 * The coordinator owns attachment metadata and the global scheduling tokens. */
typedef struct ListingJob ListingJob;
typedef struct WalkEntry {
    CuStr name;
    CuDirKind kind;
    ListingJob *prefetch;
    int eligible;
} WalkEntry;
struct ListingJob {
    CuArena arena;
    char *path;
    CuVec entries;
    int error;
    int operation;
    int state;
    int token;
};
typedef struct ListingWorker {
    Pool *pool;
    CuThread *thread;
} ListingWorker;
struct Pool {
    CuArena arena;
    CuMutex *mutex;
    CuCond *work;
    CuCond *completed;
    ListingWorker workers[32];
    ListingJob *slots[32];
    int count;
    int started;
    int ready;
    int stop;
    int pending;
};

static int listing_resource(int error)
{
    return error == ENOMEM || error == E2BIG || error == EMFILE || error == ENFILE;
}

static int entry_compare(const void *a, const void *b)
{
    const WalkEntry *x;
    const WalkEntry *y;
    x = (const WalkEntry *)a;
    y = (const WalkEntry *)b;
    return strcmp(x->name.ptr, y->name.ptr);
}

#ifndef FYND_LISTING_COLLECT
#define FYND_LISTING_COLLECT(job) ((void)0)
#endif
#ifndef FYND_PENDING
#define FYND_PENDING(pool) ((void)0)
#endif

static void listing_collect(ListingJob *job)
{
    CuDir dir;
    CuDirEntry raw;
    WalkEntry entry;
    int next;
    FYND_LISTING_COLLECT(job);
    if (job->error != 0)
        return;
    if (!cu_dir_open(&dir, &job->arena, job->path)) {
        job->error = cu_dir_errno(&dir);
        job->operation = 1;
        cu_dir_close(&dir);
        return;
    }
    while ((next = cu_dir_next(&dir, &raw)) == 1) {
        entry.name = raw.name;
        entry.kind = raw.kind;
        entry.prefetch = NULL;
        entry.eligible = 0;
        CU_VEC_PUSH(&job->entries, &entry);
        if (cu_vec_failed(&job->entries))
            break;
    }
    job->error = cu_dir_errno(&dir);
    cu_dir_close(&dir);
    job->operation = 2;
    if (cu_arena_failed(&job->arena) || cu_vec_failed(&job->entries))
        job->error = ENOMEM;
    else if (next >= 0)
        job->error = 0;
    if (job->error == 0 && job->entries.len > 1)
        qsort(job->entries.data, job->entries.len, sizeof(WalkEntry), entry_compare);
}

static void listing_init(ListingJob *job, const char *path)
{
    size_t n;
    cu_arena_init(&job->arena);
    CU_VEC_INIT(&job->entries, &job->arena, WalkEntry);
    job->error = 0;
    job->operation = 0;
    job->state = 0;
    job->token = 0;
    n = strlen(path);
    job->path = n == (size_t)-1 ? NULL : cu_arena_push_bytes(&job->arena, n + 1);
    if (job->path == NULL)
        job->error = ENOMEM;
    else
        memcpy(job->path, path, n + 1);
}

static void listing_worker(void *context)
{
    ListingWorker *worker;
    Pool *pool;
    ListingJob *job;
    int i;
    worker = (ListingWorker *)context;
    pool = worker->pool;
    cu_mutex_lock(pool->mutex);
    for (;;) {
        job = NULL;
        if (pool->ready && !pool->stop)
            for (i = 0; i < pool->count; ++i)
                if (pool->slots[i] != NULL && pool->slots[i]->state == 1) {
                    job = pool->slots[i];
                    job->state = 2;
                    break;
                }
        if (pool->stop)
            break;
        if (job == NULL) {
            cu_cond_wait(pool->work, pool->mutex);
            continue;
        }
        cu_mutex_unlock(pool->mutex);
        listing_collect(job);
        cu_mutex_lock(pool->mutex);
        job->state = 3;
        cu_cond_broadcast(pool->completed);
    }
    cu_mutex_unlock(pool->mutex);
}

static void pool_cancel(Pool *pool)
{
    int i;
    if (pool->mutex == NULL)
        return;
    cu_mutex_lock(pool->mutex);
    pool->stop = 1;
    for (i = 0; i < pool->count; ++i)
        if (pool->slots[i] != NULL && pool->slots[i]->state == 1)
            pool->slots[i]->state = 3;
    if (pool->work != NULL)
        cu_cond_broadcast(pool->work);
    if (pool->completed != NULL)
        cu_cond_broadcast(pool->completed);
    cu_mutex_unlock(pool->mutex);
}

static void pool_finish(Pool *pool)
{
    int i;
    pool_cancel(pool);
    for (i = 0; i < pool->started; ++i)
        cu_thread_join(pool->workers[i].thread);
    if (pool->completed != NULL)
        cu_cond_destroy(pool->completed);
    if (pool->work != NULL)
        cu_cond_destroy(pool->work);
    if (pool->mutex != NULL)
        cu_mutex_destroy(pool->mutex);
    cu_arena_release(&pool->arena);
}

static int pool_start(Pool *pool, int count)
{
    int i;
    cu_arena_init(&pool->arena);
    pool->mutex = NULL;
    pool->work = NULL;
    pool->completed = NULL;
    pool->count = count;
    pool->started = 0;
    pool->ready = 0;
    pool->stop = 0;
    pool->pending = 0;
    for (i = 0; i < 32; ++i) {
        pool->slots[i] = NULL;
        pool->workers[i].pool = pool;
        pool->workers[i].thread = NULL;
    }
    if (!cu_mutex_init(&pool->mutex, &pool->arena) ||
        !cu_cond_init(&pool->work, &pool->arena) ||
        !cu_cond_init(&pool->completed, &pool->arena))
        return 0;
    for (i = 0; i < count; ++i) {
        if (!cu_thread_start(&pool->workers[i].thread, &pool->arena, 0,
                             listing_worker, &pool->workers[i]))
            return 0;
        ++pool->started;
    }
    cu_mutex_lock(pool->mutex);
    pool->ready = 1;
    cu_cond_broadcast(pool->work);
    cu_mutex_unlock(pool->mutex);
    return 1;
}

static int listing_submit(Pool *pool, ListingJob *job)
{
    int i;
    int accepted;
    accepted = 0;
    cu_mutex_lock(pool->mutex);
    if (!pool->stop && pool->pending < pool->count)
        for (i = 0; i < pool->count; ++i)
            if (pool->slots[i] == NULL) {
                pool->slots[i] = job;
                job->token = 1;
                job->state = 1;
                ++pool->pending;
                FYND_PENDING(pool);
                accepted = 1;
                cu_cond_broadcast(pool->work);
                break;
            }
    cu_mutex_unlock(pool->mutex);
    return accepted;
}

/* Adoption releases capacity, never the arena or stable object. */
static void listing_adopt(Pool *pool, ListingJob *job)
{
    int i;
    if (!job->token)
        return;
    cu_mutex_lock(pool->mutex);
    while (job->state != 3)
        cu_cond_wait(pool->completed, pool->mutex);
    for (i = 0; i < pool->count; ++i)
        if (pool->slots[i] == job) {
            pool->slots[i] = NULL;
            --pool->pending;
            FYND_PENDING(pool);
            break;
        }
    job->token = 0;
    cu_mutex_unlock(pool->mutex);
}

static void listing_release(Pool *pool, ListingJob *job)
{
    size_t i;
    WalkEntry *entry;
    listing_adopt(pool, job);
    if (job->error == 0)
        for (i = 0; i < job->entries.len; ++i) {
            entry = CU_VEC_AT(&job->entries, WalkEntry, i);
            if (entry->prefetch != NULL)
                listing_release(pool, entry->prefetch);
        }
    cu_arena_release(&job->arena);
}

branch.tests/test_parallel.c:
/* Run with an external timeout: the overlap proof intentionally deadlocks if
 * collectors are serialized. No timing or sleep is used as evidence. */
#include "cu.h"
static void parallel_collect(void *opaque);
static void parallel_pending(void *opaque);
static void parallel_prefetch_scan(void);
static int parallel_dir_open(CuDir *dir, CuArena *arena, const char *path);
#define cu_dir_open parallel_dir_open
#define FYND_LISTING_COLLECT(job) parallel_collect(job)
#define FYND_PENDING(pool) parallel_pending(pool)
#define FYND_PREFETCH_SCAN() parallel_prefetch_scan()
int serial_fixture_main(void);
#define main serial_fixture_main
#include "test_fynd.c"
#undef main
#undef cu_dir_open

static int parallel_mode;
static int parallel_fault;
static int peak_pending;
static int done_pending;
static CuMutex *proof_mutex;
static CuCond *proof_changed;
static int arrived;
static int fallback_seen;
static size_t prefetch_scans;

/* Refill and this counter are coordinator-only, never collector callbacks. */
static void parallel_prefetch_scan(void)
{
    ++prefetch_scans;
}

static int suffix(const char *path, const char *ending)
{
    size_t n;
    size_t m;
    n = strlen(path);
    m = strlen(ending);
    return n >= m && strcmp(path + n - m, ending) == 0;
}

static void parallel_collect(void *opaque)
{
    ListingJob *job;
    char saved_path[160];
    char *owned_path;
    size_t path_size;
    job = (ListingJob *)opaque;
    if (parallel_fault && suffix(job->path, "/a")) {
        if (parallel_fault == 1) {
            /* The default arena already owns a block. Rebuild this empty
             * listing in place: debug mode makes the next push an attempt. */
            assert(job->entries.len == 0);
            path_size = strlen(job->path) + 1;
            assert(path_size <= sizeof saved_path);
            memcpy(saved_path, job->path, path_size);
            cu_arena_release(&job->arena);
            cu_arena_init_with(&job->arena, 64, 1);
            CU_VEC_INIT(&job->entries, &job->arena, WalkEntry);
            owned_path = cu_arena_push_bytes(&job->arena, path_size);
            assert(owned_path != NULL);
            memcpy(owned_path, saved_path, path_size);
            job->path = owned_path;
            cu_arena_fail_at(&job->arena, job->arena.attempts);
        } else {
            job->error = EIO;
            job->operation = 2;
        }
    }
    if (parallel_mode == 2) {
        cu_mutex_lock(proof_mutex);
        ++arrived;
        cu_cond_broadcast(proof_changed);
        while (!fallback_seen)
            cu_cond_wait(proof_changed, proof_mutex);
        cu_mutex_unlock(proof_mutex);
        return;
    }
    if (!parallel_mode)
        return;
    cu_mutex_lock(proof_mutex);
    if (suffix(job->path, "/a") || suffix(job->path, "/b"))
        assert(job->state == 2);
    if (suffix(job->path, "/a/x")) {
        assert(job->state == 2); /* Current branch wins the refunded token. */
        fallback_seen = 1;
        cu_cond_broadcast(proof_changed);
    }
    cu_mutex_unlock(proof_mutex);
}

static int parallel_dir_open(CuDir *dir, CuArena *arena, const char *path)
{
    int opened;
    opened = cu_dir_open(dir, arena, path);
    if (parallel_mode != 1)
        return opened;
    cu_mutex_lock(proof_mutex);
    if (suffix(path, "/a") || suffix(path, "/b")) {
        ++arrived;
        cu_cond_broadcast(proof_changed);
        while (arrived < 2)
            cu_cond_wait(proof_changed, proof_mutex);
    }
    if (suffix(path, "/b") || suffix(path, "/c"))
        while (!fallback_seen)
            cu_cond_wait(proof_changed, proof_mutex);
    cu_mutex_unlock(proof_mutex);
    return opened;
}

/* Called only by the coordinator, under the pool mutex. DONE jobs still count. */
static void parallel_pending(void *opaque)
{
    Pool *pool;
    int i;
    int count;
    pool = (Pool *)opaque;
    count = 0;
    for (i = 0; i < pool->count; ++i)
        if (pool->slots[i] != NULL) {
            ++count;
            if (pool->slots[i]->state == 3)
                done_pending = 1;
        }
    assert(count == pool->pending && count <= pool->count);
    if (count > peak_pending)
        peak_pending = count;
}

#ifndef __cerb__
static void parallel_running_cancel(const char *root)
{
    CuArena proof;
    Pool pool;
    ListingJob job;
    cu_arena_init(&proof);
    assert(cu_mutex_init(&proof_mutex, &proof));
    assert(cu_cond_init(&proof_changed, &proof));
    parallel_mode = 2;
    arrived = 0;
    fallback_seen = 0;
    assert(pool_start(&pool, 2));
    listing_init(&job, root);
    assert(listing_submit(&pool, &job));
    cu_mutex_lock(proof_mutex);
    while (arrived == 0)
        cu_cond_wait(proof_changed, proof_mutex);
    cu_mutex_unlock(proof_mutex);
    pool_cancel(&pool);
    cu_mutex_lock(pool.mutex);
    assert(job.state == 2 && pool.pending == 1);
    cu_mutex_lock(proof_mutex);
    fallback_seen = 1;
    cu_cond_broadcast(proof_changed);
    cu_mutex_unlock(proof_mutex);
    while (job.state != 3)
        cu_cond_wait(pool.completed, pool.mutex);
    assert(pool.pending == 1);
    cu_mutex_unlock(pool.mutex);
    listing_release(&pool, &job);
    assert(pool.pending == 0);
    pool_finish(&pool);
    parallel_mode = 0;
    cu_cond_destroy(proof_changed);
    cu_mutex_destroy(proof_mutex);
    cu_arena_release(&proof);
}

static void parallel_flat_fixture(const char *root)
{
    enum { entries = 256 };
    char flat[160];
    char path[192];
    char *args[5];
    FILE *file;
    int i;
    assert(snprintf(flat, sizeof flat, "%s/flat", root) > 0);
    assert(mkdir(flat, 0700) == 0);
    for (i = 0; i < entries; ++i) {
        assert(snprintf(path, sizeof path, "%s/file-%03d", flat, i) > 0);
        file = fopen(path, "w");
        assert(file != NULL);
        assert(fclose(file) == 0);
    }
    args[0] = "fynd"; args[1] = "--no-ignore"; args[2] = "-j2";
    args[3] = "nomatch"; args[4] = flat;
    prefetch_scans = 0;
    expect_call(5, args, 0, "");
    /* The repeated-suffix scan would visit 256 + ... + 1 = 32896 entries. */
    assert(prefetch_scans > 0 && prefetch_scans <= 2U * (size_t)entries);
    for (i = 0; i < entries; ++i) {
        assert(snprintf(path, sizeof path, "%s/file-%03d", flat, i) > 0);
        assert(unlink(path) == 0);
    }
    assert(rmdir(flat) == 0);
}

static void parallel_fixtures(void)
{
    char root[128];
    char path[160];
    char expected[1024];
    char duplicate[2048];
    size_t byte;
    size_t length;
    char *args[8];
    FILE *out;
    FILE *err;
    CuArena proof;
    Pool pool;
    ListingJob jobs[3];
    size_t attempt;
    int i;
    int supported;
#ifdef __wasi__
    assert(snprintf(root, sizeof root, "/tmp/fynd-parallel-wasi") > 0);
#else
    assert(snprintf(root, sizeof root, "/tmp/fynd-parallel-%ld", (long)getpid()) > 0);
#endif
    assert(mkdir(root, 0700) == 0);
    for (i = 0; i < 3; ++i) {
        assert(snprintf(path, sizeof path, "%s/%c", root, 'a' + i) > 0);
        assert(mkdir(path, 0700) == 0);
    }
    assert(snprintf(path, sizeof path, "%s/a/x", root) > 0);
    assert(mkdir(path, 0700) == 0);
    args[0] = "fynd"; args[1] = "--no-ignore"; args[2] = "-j2";
    args[3] = ""; args[4] = root;
    supported = pool_start(&pool, 2);
#ifdef __wasi__
    if (!supported)
        assert(errno == ENOSYS);
#else
    assert(supported); /* Native thread regressions must not skip overlap. */
#endif
    pool_finish(&pool);
    if (!supported) {
        expect_call(5, args, 1, "");
    } else {
        cu_arena_init(&proof);
        assert(cu_mutex_init(&proof_mutex, &proof));
        assert(cu_cond_init(&proof_changed, &proof));
        parallel_mode = 1;
        assert(snprintf(expected, sizeof expected, "%s\n%s/a\n%s/a/x\n%s/b\n%s/c\n",
                        root, root, root, root, root) > 0);
        expect_call(5, args, 0, expected);
        parallel_mode = 0; /* Every invocation has joined before hook changes. */
        assert(arrived == 2 && fallback_seen && peak_pending == 2);
        expect_call(5, args, 0, expected);
        assert(snprintf(duplicate, sizeof duplicate, "%s%s", expected, expected) > 0);
        args[5] = root;
        expect_call(6, args, 0, duplicate);
        length = strlen(duplicate);
        for (byte = 0; byte < length; ++byte)
            if (duplicate[byte] == '\n')
                duplicate[byte] = 0;
        args[3] = "-0"; args[4] = ""; args[5] = root; args[6] = root;
        expect_bytes(7, args, 0, duplicate, length);
        args[3] = ""; args[4] = root;
        cu_cond_destroy(proof_changed);
        cu_mutex_destroy(proof_mutex);
        cu_arena_release(&proof);

        /* Completed but unadopted listings keep their tokens. */
        assert(pool_start(&pool, 2));
        for (i = 0; i < 3; ++i)
            listing_init(&jobs[i], root);
        assert(listing_submit(&pool, &jobs[0]));
        assert(listing_submit(&pool, &jobs[1]));
        cu_mutex_lock(pool.mutex);
        while (jobs[0].state != 3 || jobs[1].state != 3)
            cu_cond_wait(pool.completed, pool.mutex);
        assert(pool.pending == 2);
        parallel_pending(&pool);
        cu_mutex_unlock(pool.mutex);
        assert(done_pending);
        assert(!listing_submit(&pool, &jobs[2]));
        for (i = 0; i < 3; ++i)
            listing_release(&pool, &jobs[i]);
        pool_finish(&pool);

        /* Hold the ready gate shut to exercise queued cancellation exactly. */
        assert(pool_start(&pool, 2));
        cu_mutex_lock(pool.mutex);
        pool.ready = 0;
        cu_mutex_unlock(pool.mutex);
        for (i = 0; i < 2; ++i) {
            listing_init(&jobs[i], root);
            assert(listing_submit(&pool, &jobs[i]));
        }
        pool_cancel(&pool);
        cu_mutex_lock(pool.mutex);
        assert(jobs[0].state == 3 && jobs[1].state == 3);
        cu_mutex_unlock(pool.mutex);
        for (i = 0; i < 2; ++i)
            listing_release(&pool, &jobs[i]);
        assert(pool.pending == 0);
        pool_finish(&pool);

        for (parallel_fault = 1; parallel_fault <= 2; ++parallel_fault) {
            out = tmpfile(); err = tmpfile();
            assert(out != NULL && err != NULL);
            assert(fynd_main(5, args, out, err) == 1);
            assert(fclose(out) == 0 && fclose(err) == 0);
        }
        parallel_fault = 0;
        expect_call(5, args, 0, expected);
        /* One mutex, two conditions, then every requested worker start. */
        for (attempt = 0; attempt < 5; ++attempt) {
            cu_thread_fail_at(attempt);
            expect_call(5, args, 1, "");
            cu_thread_fail_at((size_t)-1);
            expect_call(5, args, 0, expected);
        }
        cu_thread_fail_at(0);
        args[2] = "-j1";
        expect_call(5, args, 0, expected);
        cu_thread_fail_at((size_t)-1);
        args[2] = "-j2";
#ifdef __linux__
        out = fopen("/dev/full", "w"); err = tmpfile();
        assert(out != NULL && err != NULL);
        assert(setvbuf(out, NULL, _IONBF, 0) == 0);
        args[3] = "x"; /* Fail only after child listing scheduling has begun. */
        assert(fynd_main(5, args, out, err) == 1);
        args[3] = "";
        (void)fclose(out);
        assert(fclose(err) == 0);
        expect_call(5, args, 0, expected);
#endif
        parallel_running_cancel(root);
        parallel_flat_fixture(root);
    }
    assert(rmdir(path) == 0);
    for (i = 0; i < 3; ++i) {
        assert(snprintf(path, sizeof path, "%s/%c", root, 'a' + i) > 0);
        assert(rmdir(path) == 0);
    }
    assert(rmdir(root) == 0);
}
#endif

int main(void)
{
    int status;
    status = serial_fixture_main();
#ifndef __cerb__
    parallel_fixtures();
#else
    {
        char *args[3];
        FILE *out;
        FILE *err;
        Pool pool;
        assert(!pool_start(&pool, 2));
        assert(errno == ENOSYS);
        pool_finish(&pool);
        args[0] = "fynd"; args[1] = "-j2"; args[2] = "";
        out = tmpfile(); err = tmpfile();
        assert(out != NULL && err != NULL);
        assert(fynd_main(3, args, out, err) == 1);
        assert(fclose(out) == 0 && fclose(err) == 0);
    }
#endif
    return status;
}

