static void parallel_fixtures(void)
{
    char root[128];
    char path[160];
    char expected[1024];
    char duplicate[2048];
    size_t byte;
    size_t length;
    char *args[8];
    FILE *out;
    FILE *err;
    CuArena proof;
    Pool pool;
    ListingJob jobs[3];
    size_t attempt;
    int i;
    int supported;
#ifdef __wasi__
    assert(snprintf(root, sizeof root, "/tmp/fynd-parallel-wasi") > 0);
#else
    assert(snprintf(root, sizeof root, "/tmp/fynd-parallel-%ld", (long)getpid()) > 0);
#endif
